CREATE TABLE IF NOT EXISTS src_mdm.md_partner_contact(id BIGINT NOT NULL AUTO_INCREMENT,partner_type VARCHAR(16) NOT NULL,partner_id BIGINT NOT NULL,contact_name VARCHAR(50) NOT NULL,position_name VARCHAR(50) NULL,mobile VARCHAR(30) NULL,email VARCHAR(100) NULL,is_primary TINYINT(1) NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),KEY idx_contact_partner(partner_type,partner_id));
CREATE TABLE IF NOT EXISTS src_mdm.md_warehouse(id BIGINT NOT NULL AUTO_INCREMENT,warehouse_code VARCHAR(32) NOT NULL,warehouse_name VARCHAR(100) NOT NULL,factory_code VARCHAR(32) NOT NULL,warehouse_type VARCHAR(16) NULL,status VARCHAR(16) NOT NULL DEFAULT 'PUBLISHED',version_no INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_md_warehouse(warehouse_code));
CREATE TABLE IF NOT EXISTS src_mdm.md_work_center(id BIGINT NOT NULL AUTO_INCREMENT,work_center_code VARCHAR(32) NOT NULL,work_center_name VARCHAR(100) NOT NULL,workshop_code VARCHAR(32) NOT NULL,capacity_per_day DECIMAL(18,4) NULL,status VARCHAR(16) NOT NULL DEFAULT 'PUBLISHED',version_no INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_md_work_center(work_center_code));
CREATE TABLE IF NOT EXISTS src_mdm.md_production_version(id BIGINT NOT NULL AUTO_INCREMENT,production_version_code VARCHAR(32) NOT NULL,product_code VARCHAR(32) NOT NULL,bom_code VARCHAR(32) NOT NULL,bom_version VARCHAR(16) NOT NULL,routing_code VARCHAR(32) NOT NULL,routing_version VARCHAR(16) NOT NULL,factory_code VARCHAR(32) NOT NULL,effective_date DATE NOT NULL,expire_date DATE NULL,status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',version_no INT NOT NULL DEFAULT 1,created_by VARCHAR(32) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_md_prod_version(production_version_code));
CREATE TABLE IF NOT EXISTS src_mdm.md_bom_substitute(id BIGINT NOT NULL AUTO_INCREMENT,bom_line_id BIGINT NOT NULL,substitute_material_code VARCHAR(32) NOT NULL,priority_no INT NOT NULL DEFAULT 1,conversion_rate DECIMAL(18,6) NOT NULL DEFAULT 1,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_bom_substitute(bom_line_id,substitute_material_code));
CREATE TABLE IF NOT EXISTS src_mdm.md_merge_record(id BIGINT NOT NULL AUTO_INCREMENT,entity_type VARCHAR(32) NOT NULL,survivor_id BIGINT NOT NULL,merged_id BIGINT NOT NULL,survivor_code VARCHAR(64) NOT NULL,merged_code VARCHAR(64) NOT NULL,reason VARCHAR(500) NOT NULL,operator VARCHAR(32) NOT NULL,merged_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_merge_source(entity_type,merged_id));
CREATE TABLE IF NOT EXISTS src_mdm.md_code_mapping(id BIGINT NOT NULL AUTO_INCREMENT,entity_type VARCHAR(32) NOT NULL,old_code VARCHAR(64) NOT NULL,current_code VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_code_mapping(entity_type,old_code));
CREATE TABLE IF NOT EXISTS src_mdm.md_change_history(id BIGINT NOT NULL AUTO_INCREMENT,entity_type VARCHAR(32) NOT NULL,entity_id BIGINT NOT NULL,entity_code VARCHAR(64) NOT NULL,action VARCHAR(32) NOT NULL,before_json JSON NULL,after_json JSON NULL,operator VARCHAR(32) NOT NULL,changed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),KEY idx_change_entity(entity_type,entity_id));
CREATE TABLE IF NOT EXISTS src_mdm.md_outbox(event_id VARCHAR(64) NOT NULL,event_type VARCHAR(64) NOT NULL,aggregate_type VARCHAR(32) NOT NULL,aggregate_id BIGINT NOT NULL,aggregate_code VARCHAR(64) NOT NULL,aggregate_version INT NOT NULL,payload JSON NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',retry_count INT NOT NULL DEFAULT 0,error_message VARCHAR(500) NULL,occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),processed_at DATETIME(3) NULL,PRIMARY KEY(event_id),KEY idx_outbox_status(status,occurred_at));
CREATE TABLE IF NOT EXISTS src_mdm.md_inbox(id BIGINT NOT NULL AUTO_INCREMENT,event_id VARCHAR(64) NOT NULL,target_system VARCHAR(16) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',retry_count INT NOT NULL DEFAULT 0,error_message VARCHAR(500) NULL,received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),processed_at DATETIME(3) NULL,PRIMARY KEY(id),UNIQUE KEY uk_inbox_event_target(event_id,target_system));
CREATE TABLE IF NOT EXISTS src_mdm.md_reconciliation(id BIGINT NOT NULL AUTO_INCREMENT,event_id VARCHAR(64) NOT NULL,target_system VARCHAR(16) NOT NULL,entity_code VARCHAR(64) NOT NULL,source_version INT NOT NULL,target_version INT NULL,source_hash VARCHAR(64) NULL,target_hash VARCHAR(64) NULL,result VARCHAR(16) NOT NULL,message VARCHAR(500) NULL,checked_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),KEY idx_recon_event(event_id));
ALTER TABLE mfg_auth.wf_task ADD COLUMN assigned_user VARCHAR(32) NULL AFTER approver_role,ADD COLUMN source_task_id BIGINT NULL AFTER assigned_user,ADD COLUMN sign_mode VARCHAR(16) NULL AFTER source_task_id;
CREATE TABLE IF NOT EXISTS mfg_auth.wf_cc(id BIGINT NOT NULL AUTO_INCREMENT,instance_id BIGINT NOT NULL,username VARCHAR(32) NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_by VARCHAR(32) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),read_at DATETIME(3) NULL,PRIMARY KEY(id),UNIQUE KEY uk_wf_cc(instance_id,username));
